package main

import (
	"crypto/tls"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"net/url"
	"os"
	"strings"
)

type WebhookRequest struct {
	CallbackURL string `json:"callback_url"`
	EventType   string `json:"event_type"`
	Payload     string `json:"payload"`
}

type SignedResponse struct {
	Status    string `json:"status"`
	Signature string `json:"signature"`
	KeyID     string `json:"key_id"`
}

var hsmEndpoint string
var signingKeyID string

func init() {
	hsmEndpoint = os.Getenv("HSM_ENDPOINT")
	if hsmEndpoint == "" {
		hsmEndpoint = "https://hsm-proxy.internal:9223"
	}
	signingKeyID = os.Getenv("HSM_KEY_ID")
	if signingKeyID == "" {
		signingKeyID = "arn:aws:kms:us-east-1:111122223333:key/abcd-1234"
	}
}

func signPayload(data []byte) (string, error) {
	client := &http.Client{
		Transport: &http.Transport{
			TLSClientConfig: &tls.Config{InsecureSkipVerify: false},
		},
	}
	req, err := http.NewRequest("POST", hsmEndpoint+"/sign", strings.NewReader(string(data)))
	if err != nil {
		return "", err
	}
	req.Header.Set("X-Key-ID", signingKeyID)
	req.Header.Set("Content-Type", "application/octet-stream")
	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("HSM signing failed: %v", err)
	}
	defer resp.Body.Close()
	body, _ := ioutil.ReadAll(resp.Body)
	return string(body), nil
}

func webhookHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req WebhookRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	if req.CallbackURL == "" {
		http.Error(w, "callback_url required", 400)
		return
	}

	// Validate URL scheme
	parsed, err := url.Parse(req.CallbackURL)
	if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") {
		http.Error(w, "Invalid callback URL scheme", 400)
		return
	}

	// Sign the payload via HSM
	signature, err := signPayload([]byte(req.Payload))
	if err != nil {
		log.Printf("Signing error: %v", err)
		http.Error(w, "Internal signing error", 500)
		return
	}

	// Deliver signed payload to callback URL
	signedResp := SignedResponse{
		Status:    "processed",
		Signature: signature,
		KeyID:     signingKeyID,
	}
	jsonBody, _ := json.Marshal(signedResp)

	// SSRF: user-controlled callback_url is fetched server-side
	callbackReq, err := http.NewRequest("POST", req.CallbackURL, strings.NewReader(string(jsonBody)))
	if err != nil {
		http.Error(w, "Failed to create callback request", 500)
		return
	}
	callbackReq.Header.Set("Content-Type", "application/json")

	client := &http.Client{}
	resp, err := client.Do(callbackReq)
	if err != nil {
		log.Printf("Callback delivery failed: %v", err)
		http.Error(w, "Callback delivery failed", 502)
		return
	}
	defer resp.Body.Close()

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]interface{}{
		"delivered":    true,
		"callback_status": resp.StatusCode,
		"signature":    signature,
	})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/webhook", webhookHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting webhook-signer service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
